SELECT 
  ROUND(
    (SELECT COUNT(*) FROM atom WHERE element = 'c' AND molecule_id IN (
      SELECT molecule_id FROM bond WHERE bond_type = '='
    )) / 
    (SELECT COUNT(*) FROM atom WHERE molecule_id IN (
      SELECT molecule_id FROM bond WHERE bond_type = '='
    )) * 100, 2
  ) AS percentage	----- bird -----	toxicology

